WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_nov_speech'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '情景模拟演讲', 'kp-ms-nov-speech', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "新颖题型：情景模拟演讲"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "角色代入感。你不再是考生，而是特定的身份（如村支书、调解员）。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、破题心法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题型最考验“对象感”。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "面对村民演讲：绝对不能打官腔、背政策！要用大白话，“乡亲们呐”、“大爷大妈们”。多算经济账，用身边人的例子去说服他们。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "面对企业老板演讲：要用规范的商业术语，强调政策红利、法治环境和合作共赢。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "面对沮丧的下属演讲（谈心）：要体现共情，先肯定他的付出，再帮他分析困难，最后给出实质性的支持和鼓励。"}]}]}]}]}$$ AS jsonb), NULL, '情景模拟演讲的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "新颖题型", "情景模拟"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_nov_speech", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
